# Reference interpreter for the Logomocja dialect (scratch; used only to compute expectations and cross-check).
import math, re

class LogoError(Exception):
    def __init__(self, msg, line, col):
        super().__init__(msg); self.msg=msg; self.line=line; self.col=col

class Tok:
    def __init__(self, type, val, line, col):
        self.type=type; self.val=val; self.line=line; self.col=col; self.wsb=True; self.wsa=True
    def __repr__(self): return f"{self.type}:{self.val}@{self.line}:{self.col}"

WORD_RE = re.compile(r'[^\W\d]\w*', re.UNICODE)
NUM_RE = re.compile(r'\d+(?:\.\d+)?|\.\d+')
COLOR_RE = re.compile(r'"#[0-9a-fA-F]{6}"')

def tokenize(src):
    if len(src) > 50000: raise LogoError('source too long', 1, 1)
    toks=[]; i=0; line=1; col=1; n=len(src); prev_ws=True
    while i<n:
        c=src[i]
        if c=='\n':
            toks.append(Tok('NL',None,line,col)); i+=1; line+=1; col=1; prev_ws=True; continue
        if c in ' \t\r':
            i+=1; col+=1; prev_ws=True; continue
        if c==';':
            while i<n and src[i]!='\n': i+=1; col+=1
            prev_ws=True; continue
        sl, sc = line, col
        m = NUM_RE.match(src, i)
        if m and (c.isdigit() or c=='.'):
            t=Tok('NUM', float(m.group()), sl, sc); L=len(m.group())
        else:
            m = WORD_RE.match(src, i)
            if m:
                t=Tok('NAME', m.group().lower(), sl, sc); L=len(m.group())
            elif c=='"':
                m=COLOR_RE.match(src, i)
                if not m: raise LogoError('malformed colour', sl, sc)
                t=Tok('COLOR', m.group()[1:-1].lower(), sl, sc); L=len(m.group())
            elif c in '[]()':
                t=Tok({'[':'LB',']':'RB','(':'LP',')':'RP'}[c], c, sl, sc); L=1
            elif c==',': t=Tok('COMMA', c, sl, sc); L=1
            elif c==':': t=Tok('COLON', c, sl, sc); L=1
            elif c in '+-*/': t=Tok('OP', c, sl, sc); L=1
            elif src.startswith('<=',i) or src.startswith('>=',i) or src.startswith('<>',i):
                t=Tok('CMP', src[i:i+2], sl, sc); L=2
            elif c in '<>=': t=Tok('CMP', c, sl, sc); L=1
            else: raise LogoError('bad character', sl, sc)
        t.wsb=prev_ws
        i+=L; col+=L
        t.wsa = (i>=n) or src[i] in ' \t\r\n;'
        prev_ws=False
        toks.append(t)
    real=[t for t in toks if t.type!='NL']
    if len(real) > 10000: raise LogoError('too many tokens', real[10000].line, real[10000].col)
    return toks

