class Parser:
    def __init__(self, toks, procs, globals_declared, mode):
        self.toks=toks; self.i=0; self.procs=procs; self.globals=globals_declared; self.mode=mode
        self.params=set(); self.locals=set(); self.in_proc=False; self.depth=0
    def peek(self): return self.toks[self.i] if self.i<len(self.toks) else None
    def next(self): t=self.peek(); self.i+=1; return t
    def eof_err(self, msg):
        if self.toks: t=self.toks[-1]; raise LogoError(msg+' (eof)', t.line, t.col)
        raise LogoError(msg+' (eof)', 1, 1)
    def block(self, repeat_depth, stop_at_rb):
        stmts=[]
        while True:
            t=self.peek()
            if t is None:
                if stop_at_rb: self.eof_err('missing ]')
                return stmts
            if t.type=='RB':
                if stop_at_rb: self.next(); return stmts
                raise LogoError('stray ]', t.line, t.col)
            stmts.append(self.statement(repeat_depth))
    def need_block(self, repeat_depth):
        t=self.peek()
        if t is None: self.eof_err('missing [')
        if t.type!='LB': raise LogoError('expected [', t.line, t.col)
        self.next(); self.depth+=1
        if self.depth>32: raise LogoError('nesting too deep', t.line, t.col)
        b=self.block(repeat_depth, True); self.depth-=1; return b
    def statement(self, rd):
        t=self.next()
        if t.type!='NAME': raise LogoError('stray value', t.line, t.col)
        name=t.val
        if name in ('oto','to'): raise LogoError('definition inside body', t.line, t.col)
        if name in ('już','juz','end'): raise LogoError('stray end', t.line, t.col)
        c=CMDS.get(name)
        if c in MOVE:
            if self.mode=='2d' and c in THREED: raise LogoError('3d only', t.line, t.col)
            e=self.expr(rd, 'argument'); return ('move', c, e, t)
        if c in ('pu','pd','stop','home','cs'): return (c, t)
        if c=='color':
            a=self.peek()
            if a is None: self.eof_err('missing colour')
            if a.type!='COLOR': raise LogoError('malformed colour', a.line, a.col)
            self.next(); return ('color', a.val, t)
        if c=='width':
            e=self.expr(rd,'width')
            if not has_name(e):
                v=const_eval(e)
                if v is None or v!=int(v) or not (1<=v<=12): raise LogoError('bad width', e[-1].line, e[-1].col)
            return ('width', e, t)
        if c=='repeat':
            e=self.expr(rd,'count')
            if not has_name(e):
                v=const_eval(e)
                if v is None or v!=int(v) or not (0<=v<=10000): raise LogoError('bad count', e[-1].line, e[-1].col)
            b=self.need_block(rd+1); return ('repeat', e, b, t)
        if c=='let':
            a=self.peek()
            if a is None: self.eof_err('missing name')
            if a.type!='NAME' or a.val in RESERVED or a.val in self.procs: raise LogoError('bad variable name', a.line, a.col)
            self.next(); e=self.expr(rd,'value'); return ('let', a.val, e, t)
        if c=='if':
            cond=self.cond(rd); b=self.need_block(rd); return ('if', cond, b, t)
        if c=='ifelse':
            cond=self.cond(rd); b1=self.need_block(rd); b2=self.need_block(rd); return ('ifelse', cond, b1, b2, t)
        if name in self.procs:
            np_=len(self.procs[name]['params']); args=[self.expr(rd,'argument') for _ in range(np_)]
            return ('call', name, args, t)
        raise LogoError('unknown command', t.line, t.col)
    def cond(self, rd):
        l=self.expr(rd,'condition'); t=self.peek()
        if t is None: self.eof_err('missing comparison')
        if t.type!='CMP': raise LogoError('expected comparison', t.line, t.col)
        self.next(); r=self.expr(rd,'condition'); return (l, t.val, r)
    def expr(self, rd, what):
        t=self.peek()
        if t is None: self.eof_err('missing '+what)
        e=self.additive(rd); return e+(t,)   # append first token
    def additive(self, rd):
        e=self.term(rd)
        while True:
            t=self.peek()
            if t and t.type=='OP' and t.val in '+-' and t.wsb==t.wsa:
                self.next(); e=('bin', t.val, e, self.term(rd), t)
            else: return e
    def term(self, rd):
        e=self.unary(rd)
        while True:
            t=self.peek()
            if t and t.type=='OP' and t.val in '*/' and t.wsb==t.wsa:
                self.next(); e=('bin', t.val, e, self.unary(rd), t)
            else: return e
    def unary(self, rd):
        t=self.peek()
        if t is None: self.eof_err('missing operand')
        if t.type=='OP' and t.val in '+-':
            self.next(); return ('neg' if t.val=='-' else 'pos', self.unary(rd), t)
        if t.type=='NUM': self.next(); return ('num', t.val, t)
        if t.type=='LP':
            self.next(); e=self.additive(rd); r=self.peek()
            if r is None: self.eof_err('missing )')
            if r.type!='RP': raise LogoError('expected )', r.line, r.col)
            self.next(); return e
        if t.type=='COLON':
            self.next(); nt=self.peek()
            if nt is None or nt.type!='NAME': raise LogoError('bad :name', t.line, t.col)
            self.next(); return self.nameref(nt.val, t, rd)
        if t.type=='NAME':
            if t.val in ('nrpowt','repcount'):
                if rd==0: raise LogoError('nrpowt outside repeat', t.line, t.col)
                self.next(); return ('repcount', t)
            if t.val in RESERVED: raise LogoError('malformed argument', t.line, t.col)
            self.next(); return self.nameref(t.val, t, rd)
        raise LogoError('malformed argument', t.line, t.col)
    def nameref(self, nm, t, rd):
        if nm in self.params or nm in self.locals or nm in self.globals: return ('var', nm, t)
        raise LogoError('undeclared name '+nm, t.line, t.col)

def has_name(e):
    k=e[0]
    if k=='var' or k=='repcount': return True
    if k=='bin': return has_name(e[2]) or has_name(e[3])
    if k in ('neg','pos'): return has_name(e[1])
    return False
def const_eval(e):
    try: return ev(e, None)
    except ZeroDivisionError: return None
    except OverflowError: return None

class RT(Exception): pass

def ev(e, env):
    k=e[0]
    if k=='num': return e[1]
    if k=='neg': return -ev(e[1], env)
    if k=='pos': return ev(e[1], env)
    if k=='repcount': return env.repstack[-1]
    if k=='var':
        nm=e[1]
        if env.frames and nm in env.frames[-1]: return env.frames[-1][nm]
        if nm in env.globals: return env.globals[nm]
        raise RT('unassigned')
    if k=='bin':
        a=ev(e[2],env); b=ev(e[3],env); op=e[1]
        if op=='+': r=a+b
        elif op=='-': r=a-b
        elif op=='*': r=a*b
        else:
            if b==0: raise RT('division by zero')
            r=a/b
        if not math.isfinite(r): raise RT('non-finite')
        return r
    raise Exception('bad node '+k)

class Stop(Exception): pass

class Env:
    def __init__(self, procs, mode):
        self.procs=procs; self.mode=mode; self.globals={}; self.frames=[]; self.repstack=[]
        self.pos=[0.0,0.0,0.0]; self.H=[0.0,1.0,0.0]; self.R=[1.0,0.0,0.0]; self.U=[0.0,0.0,1.0]
        self.pen=True; self.color='#16866a'; self.width=3; self.segs=[]; self.ops=0; self.depth=0
    def op(self, t):
        self.ops+=1
        if self.ops>10000: raise LogoError('operation limit', t.line, t.col)
    def push(self, t):
        self.depth+=1
        if self.depth>32: raise LogoError('frame limit', t.line, t.col)
    def pop(self): self.depth-=1
    def arg(self, e):
        try: return ev(e, self)
        except RT as x:
            ft=e[-1]; raise LogoError(str(x), ft.line, ft.col)
    def move(self, d, t):
        if d==0: return
        new=[self.pos[i]+d*self.H[i] for i in range(3)]
        for v in new:
            if abs(v)>100000: raise LogoError('coordinate limit', t.line, t.col)
        if self.pen:
            self.segs.append({'from':list(self.pos),'to':new,'color':self.color,'width':self.width})
            if len(self.segs)>10000: raise LogoError('segment limit', t.line, t.col)
        self.pos=new
    def rot(self, a, b, deg):
        # rotate vector a towards vector b by deg; returns (a', b')
        r=math.radians(deg); c=math.cos(r); s=math.sin(r)
        a2=[a[i]*c+b[i]*s for i in range(3)]; b2=[b[i]*c-a[i]*s for i in range(3)]
        return a2,b2
    def run_block(self, stmts):
        for s in stmts: self.exec(s)
        self.ops+=1
        if self.ops>10000:
            t=stmts[-1][-1] if stmts else None
            raise LogoError('operation limit', t.line if t else 1, t.col if t else 1)
    def exec(self, s):
        k=s[0]; t=s[-1]; self.op(t)
