            l,op,r=s[1]; a=self.arg(l); b=self.arg(r)
            res={'<':a<b,'>':a>b,'=':a==b,'<=':a<=b,'>=':a>=b,'<>':a!=b}[op]
            if res: self.run_block(s[2])
            elif k=='ifelse': self.run_block(s[3])
        elif k=='stop': raise Stop()
        elif k=='home':
            if self.pos!=[0.0,0.0,0.0]:
                if self.pen: self.segs.append({'from':list(self.pos),'to':[0.0,0.0,0.0],'color':self.color,'width':self.width})
                self.pos=[0.0,0.0,0.0]
            self.H=[0.0,1.0,0.0]; self.R=[1.0,0.0,0.0]; self.U=[0.0,0.0,1.0]
        elif k=='cs': self.segs=[]
        elif k=='call':
            p=self.procs[s[1]]; vals=[self.arg(a) for a in s[2]]
            self.push(t); self.frames.append(dict(zip(p['params'], vals)))
            saved=self.repstack; self.repstack=[]
            try: self.run_block(p['body'])
            except Stop: pass
