def split_defs(toks):
    lines=[]; cur=[]
    for t in toks:
        if t.type=='NL': lines.append(cur); cur=[]
        else: cur.append(t)
    lines.append(cur)
    top=[]; defs=[]; cur_def=None
    for ln in lines:
        if not ln: continue
        f=ln[0]
        if f.type=='NAME' and f.val in ('oto','to'):
            if cur_def is not None: raise LogoError('definition inside definition', f.line, f.col)
            cur_def={'hdr':ln, 'body':[]}; continue
        if cur_def is not None:
            if len(ln)==1 and ln[0].type=='NAME' and ln[0].val in ('już','juz','end'):
                defs.append(cur_def); cur_def=None
            else: cur_def['body'].extend(ln)
        else: top.extend(ln)
    if cur_def is not None:
        f=cur_def['hdr'][0]; raise LogoError('missing już', f.line, f.col)
    return top, defs

def parse_header(hdr):
    oto=hdr[0]
    if len(hdr)<2 or hdr[1].type!='NAME' or hdr[1].val in RESERVED:
        t=hdr[1] if len(hdr)>1 else oto; raise LogoError('bad procedure name', t.line, t.col)
    name=hdr[1].val; params=[]; rest=hdr[2:]
    if rest and rest[0].type=='NAME' and rest[0].val=='ma' and len(rest)>1 and rest[1].type=='COLON':
        rest=rest[2:]; expect_name=True
        for t in rest:
            if expect_name:
                if t.type!='NAME' or t.val in RESERVED: raise LogoError('bad parameter', t.line, t.col)
                params.append(t.val); expect_name=False
            else:
                if t.type!='COMMA': raise LogoError('bad header', t.line, t.col)
                expect_name=True
        if expect_name and params: raise LogoError('bad header', hdr[-1].line, hdr[-1].col)
    else:
        i=0
        while i<len(rest):
            if rest[i].type=='COLON' and i+1<len(rest) and rest[i+1].type=='NAME' and rest[i+1].val not in RESERVED:
                params.append(rest[i+1].val); i+=2
            else: raise LogoError('bad header', rest[i].line, rest[i].col)
    if len(set(params))!=len(params): raise LogoError('duplicate parameter', hdr[1].line, hdr[1].col)
    return name, params

def scan_lets(toks):
    s=set()
    for i,t in enumerate(toks):
        if t.type=='NAME' and CMDS.get(t.val)=='let' and i+1<len(toks) and toks[i+1].type=='NAME': s.add(toks[i+1].val)
    return s

def run(src, mode):
    try:
        toks=tokenize(src)
        top, defs = split_defs(toks)
        procs={}
        for d in defs:
            name, params = parse_header(d['hdr'])
            if name in procs: raise LogoError('duplicate procedure', d['hdr'][1].line, d['hdr'][1].col)
            procs[name]={'params':params,'body':None,'toks':d['body'],'hdr':d['hdr']}
        gl=scan_lets(top)
        for name,p in procs.items():
            ps=Parser(p['toks'], procs, gl, mode); ps.params=set(p['params']); ps.locals=scan_lets(p['toks']); ps.in_proc=True
            p['body']=ps.block(0, False)
        ps=Parser(top, procs, gl, mode)
        prog=ps.block(0, False)
        env=Env(procs, mode)
        try: env.run_block(prog)
        except Stop: pass
        return {'segments':env.segs, 'error':None}
    except LogoError as e:
        segs = env.segs if 'env' in locals() else []
        return {'segments':segs, 'error':{'message':e.msg,'line':e.line,'column':e.col}}

