    def next(self): t=self.peek(); self.i+=1; return t
    def eof_err(self, msg):
        if self.toks: t=self.toks[-1]; raise LogoError(msg+' (eof)', t.line, t.col)
        raise LogoError(msg+' (eof)', 1, 1)
    def block(self, repeat_depth, stop_at_rb):
        stmts=[]
