            a=self.peek()
            if a is None: self.eof_err('missing name')
            if a.type!='NAME' or a.val in RESERVED or a.val in self.procs: raise LogoError('bad variable name', a.line, a.col)
            self.next(); e=self.expr(rd,'value'); return ('let', a.val, e, t)
