            elif c=='lt': self.H,self.R=self.rot(self.H,self.R,-d)
            elif c=='pitchup': self.H,self.U=self.rot(self.H,self.U,d)
            elif c=='pitchdown': self.H,self.U=self.rot(self.H,self.U,-d)
            elif c=='rr': self.U,self.R=self.rot(self.U,self.R,d)
            elif c=='rl': self.U,self.R=self.rot(self.U,self.R,-d)
        elif k=='pu': self.pen=False
        elif k=='pd': self.pen=True
        elif k=='color': self.color=s[1]
        elif k=='width':
            w=self.arg(s[1]); ft=s[1][-1]
            if w!=int(w) or not (1<=w<=12): raise LogoError('bad width', ft.line, ft.col)
            self.width=int(w)
        elif k=='repeat':
            n=self.arg(s[1]); ft=s[1][-1]
